import json, subprocess
from pathlib import Path

repo_role_dir = Path('modules/home-manager/agents/files/pi/herdr-subagents/roles')
repo_role_dir.mkdir(parents=True, exist_ok=True)
old = json.loads(subprocess.check_output([
    'git', 'show', 'HEAD:modules/home-manager/agents/files/pi/herdr-subagents.json'
], text=True))
for name, role in old['roles'].items():
    lines = ['---']
    if 'description' in role:
        lines.append('description: ' + json.dumps(role['description'], ensure_ascii=False))
    if 'model' in role:
        if isinstance(role['model'], list):
            lines.append('model:')
            lines.extend(f'  - {model}' for model in role['model'])
        else:
            lines.append(f'model: {role["model"]}')
    if 'thinking' in role:
        lines.append(f'thinking: {role["thinking"]}')
    lines.extend(['---', '', role['prompt'], ''])
    (repo_role_dir / f'{name}.md').write_text('\n'.join(lines))

path = Path('modules/home-manager/agents/pi.nix')
text = path.read_text()
start = text.index('    ".pi/agent/herdr-subagents/roles/explore.md".text = \'\'')
end = text.index('    ".pi/agent/extensions" = {', start)
replacement = '''    ".pi/agent/herdr-subagents/roles" = {
      source = ./files/pi/herdr-subagents/roles;
      recursive = true;
    };

'''
path.write_text(text[:start] + replacement + text[end:])
